export function s_length(x) { return [typeof x, x.length]; }
export function s_index(x, y) { return x.indexOf(y); }
export function s_scan(x) { let n = 0; for (let i = 0; i < x.length; i++) if (x[i] === "a" || x[i] === 1) n++; return n; }
export function s_code(x) { return x.charCodeAt(0); }
export function s_concat(x, y) { return x + y; }
export function s_template(x) { return `<${x}>`; }
export function s_equal(x, y) { return [x === y, x == y, x < y, Object.is(x, y)]; }
export function s_slice(x) { return x.slice(1); }
export function s_switch(x) { switch (x) { case "a": return 1; case "1": return 2; case 1: return 3; default: return 0; } }
export function s_key(x) { return { a: "at a", 1: "at 1", null: "at null", undefined: "at undefined" }[x]; }
export function s_truthy(x) { return x ? "yes" : "no"; }
export function s_typeof(x) { return typeof x === "string" ? "a string" : typeof x; }
export function s_spread(x) { return [...x]; }
export function s_stored(x) { const held = { x }; held.x += "!"; return held; }
